#!/usr/bin/env bash
# Generated by Suite Builder. EDIT RULES: do not edit this file; regenerating replaces all of it. Your Jira names go in jira/jira.properties; when it runs, in the pipeline files.
# The stories job (G-208), the same in every pipeline: what Jira reported since, the stories now ready
# pulled in, the AI crew's pass over them (Claude Code, /stories), the suite's own checks, and each
# outcome reported back to Jira. The pipeline file then proposes what changed as a pull request.
# Needs JIRA_API_TOKEN (and JIRA_EMAIL on Jira Cloud) and ANTHROPIC_API_KEY, from the pipeline's secrets.
set -euo pipefail
cd "$(dirname "$0")/.."

node jira/sync.mjs report
node jira/sync.mjs pull
if [ -z "$(git status --porcelain -- stories)" ]; then
  echo "No story to work on."
  exit 0
fi
if [ -z "${ANTHROPIC_API_KEY:-}" ]; then
  echo "ANTHROPIC_API_KEY is not set: add it to the pipeline's secrets (never to a file in the suite)."
  exit 1
fi

# The dependencies, once, so the crew's checks run offline.
mvn -B -q test -Dtest=SuiteRulesTest
npx --yes @anthropic-ai/claude-code -p "/stories" --permission-mode acceptEdits --allowedTools "Read,Glob,Grep,Edit,Write,Bash(mvn -o:*)"
# The crew was told to run these; they are run again, so nothing it reports is unchecked.
# A failure here stops the job with nothing reported or proposed: the cards stay ready, and a person looks.
mvn -B -q -o test-compile
mvn -B -o test -Dtest=SuiteRulesTest
node jira/sync.mjs report
